export type Channel = 'sms' | 'email';
export type UserRole = 'customer' | 'manager' | 'admin' | 'super_admin' | 'support' | 'content_manager' | 'finance';
export type User = { id: string; phone?: string; email?: string; fullName?: string; avatarUrl?: string; avatarMediaId?: string; lastLoginAt?: string; lastLoginIp?: string; marketingEmailOptIn?: boolean; marketingSmsOptIn?: boolean; marketingInAppOptIn?: boolean; status: 'active' | 'blocked' | 'pending'; role: UserRole; createdAt: string; updatedAt: string };
export type ServiceStatus = 'active' | 'hidden' | 'maintenance' | 'archived';
export type ServiceKey = 'flights' | 'hotels' | 'homes' | 'visa' | 'tours' | 'esim';
export type Tour = { id: string; slug: string; title: string; country: string; tourType: string; destinations: string[]; durationDays: number; durationNights: number; description: string; imageUrl: string; mediaId?: string; metadata: Record<string, unknown>; priceBdt: number; status: 'draft' | 'published' | 'archived'; featured: boolean; createdBy?: string; createdAt: string; updatedAt: string };
export type TourFilters = { q?: string; country?: string; tourType?: string; status?: Tour['status'] | 'all'; maxPrice?: number; sort?: 'newest' | 'price_asc' | 'price_desc' };
export type CreateTour = Omit<Tour, 'id' | 'createdAt' | 'updatedAt'>;
export type UpdateTour = Partial<Omit<CreateTour, 'createdBy'>>;
export type OtpChallenge = { id: string; identity: string; channel: Channel; codeHash: string; attempts: number; maxAttempts: number; expiresAt: string; consumedAt?: string; requestIp?: string; purpose?: string; userId?: string; targetIdentity?: string; createdAt: string };
export type Session = { id: string; userId: string; refreshJti: string; userAgent?: string; ip?: string; expiresAt: string; revokedAt?: string; createdAt: string };
export type BookingStatus = 'new' | 'reviewing' | 'accepted' | 'processing' | 'pending' | 'confirmed' | 'completed' | 'rejected' | 'cancelled' | 'failed';
export type Booking = { id: string; userId: string; vertical: 'flight' | 'hotel' | 'home' | 'visa' | 'esim' | 'tour'; status: BookingStatus; providerRef?: string; ownerId?: string; internalNote?: string; request: unknown; response?: unknown; createdAt: string; updatedAt: string };
export type BookingEvent = { id: string; bookingId: string; actorId?: string; action: string; fromStatus?: BookingStatus; toStatus?: BookingStatus; note?: string; createdAt: string };
export type AdminBooking = Booking & { customer?: User; owner?: User };
export type AdminBookingFilters = { q?: string; status?: BookingStatus | 'needs_review' | 'all'; vertical?: Booking['vertical'] | 'all'; ownerId?: string; page?: number; pageSize?: number };
export type PaymentStatus = 'created' | 'pending' | 'paid' | 'failed' | 'refunded' | 'partially_refunded';
export type Payment = { id: string; bookingId: string; userId: string; provider: string; amount: number; currency: string; status: PaymentStatus; transactionRef?: string; providerPayload?: unknown; createdAt: string; updatedAt: string };
export type AdminPayment = Payment & { customer?: User; booking?: Booking };
export type SupportStatus = 'open' | 'pending' | 'in_progress' | 'waiting_customer' | 'resolved' | 'closed';
export type SupportPriority = 'low' | 'normal' | 'high' | 'urgent';
export type SupportTicket = { id: string; userId?: string; name: string; mobile: string; email: string; subject: string; status: SupportStatus; priority: SupportPriority; assignedTo?: string; assignedToName?: string; createdAt: string; updatedAt: string };
export type SupportMessage = { id: string; ticketId: string; authorId?: string; authorType: 'customer' | 'admin' | 'system'; message: string; internal: boolean; createdAt: string };
export type NotificationStatus = 'queued' | 'sent' | 'failed' | 'read';
export type Notification = { id: string; userId: string; title: string; message: string; channels: ('in_app' | 'sms' | 'email')[]; status: NotificationStatus; readAt?: string; sentAt?: string; failureReason?: string; createdBy?: string; createdAt: string };
export type AdminSetting = { key: string; value?: string; configured: boolean; masked?: string; secret: boolean; updatedBy?: string; updatedAt?: string };
export type ServiceVisibility = { key: ServiceKey; label: string; icon: string; status: ServiceStatus; updatedBy?: string; updatedAt?: string };
export type MediaStatus = 'active' | 'archived' | 'failed';
export type MediaAsset = { id: string; publicId: string; secureUrl: string; originalFilename: string; mimeType: string; format: string; width?: number; height?: number; bytes: number; folder: string; altText?: string; uploadedBy?: string; status: MediaStatus; createdAt: string; updatedAt: string };
export type AdminNavItem = { id: string; groupName: string; parentId?: string; label: string; route: string; icon: string; permission?: string; sortOrder: number; visible: boolean; enabled: boolean; createdAt: string; updatedAt: string };
export type CreateNavItem = Omit<AdminNavItem, 'id' | 'createdAt' | 'updatedAt'>;
export type UpdateNavItem = Partial<Omit<CreateNavItem, 'createdBy'>>;
export type TravelAgentStatus = 'active' | 'hidden' | 'archived';
export type TravelAgent = { id: string; fullName: string; agencyName?: string; photoUrl?: string; photoPublicId?: string; mediaId?: string; jobTitle?: string; department?: string; phone?: string; whatsapp?: string; email?: string; officeLocation?: string; city?: string; shortBio?: string; fullDescription?: string; languages: string[]; experienceYears?: number; specialization?: string; workingHours?: string; status: TravelAgentStatus; featured: boolean; displayOrder: number; createdBy?: string; updatedBy?: string; createdAt: string; updatedAt: string };
export type CampaignChannel = 'email' | 'sms' | 'in_app';
export type CampaignStatus = 'draft' | 'scheduled' | 'queued' | 'processing' | 'completed' | 'partially_failed' | 'failed' | 'cancelled' | 'archived';
export type Campaign = { id: string; name: string; title?: string; description?: string; imageUrl?: string; imagePublicId?: string; imageMediaId?: string; cta?: string; ctaUrl?: string; startDate?: string; endDate?: string; channels: CampaignChannel[]; status: CampaignStatus; subject?: string; preheader?: string; senderName?: string; senderEmail?: string; emailHtml?: string; emailText?: string; smsMessage?: string; webTitle?: string; webMessage?: string; webCtaText?: string; webCtaUrl?: string; segmentId?: string; recipientFilter: Record<string, unknown>; scheduledAt?: string; timezone?: string; totalRecipients: number; queuedCount: number; sentCount: number; deliveredCount: number; failedCount: number; readCount: number; createdBy?: string; createdAt: string; updatedAt: string };
