export type CampaignTemplate = { id: string; name: string; type: CampaignChannel; subject?: string; content: string; metadata: Record<string, unknown>; status: 'active' | 'archived'; createdBy?: string; createdAt: string; updatedAt: string };
export type CustomerSegment = { id: string; name: string; description?: string; rules: Record<string, unknown>; status: 'active' | 'archived'; createdBy?: string; createdAt: string; updatedAt: string };
export type CreateCampaign = Omit<Campaign,'id'|'totalRecipients'|'queuedCount'|'sentCount'|'deliveredCount'|'failedCount'|'readCount'|'createdAt'|'updatedAt'> & { createdBy?: string };
export type UpdateCampaign = Partial<Omit<CreateCampaign,'createdBy'>>;
export type CampaignQueueItem = CampaignRecipient & { recipient?: User; campaign?: Campaign };
export type SettingPatch = Record<string, string | undefined>;
export type ContentType = 'homepage' | 'destination' | 'hotel' | 'home' | 'visa' | 'esim' | 'offer' | 'airline' | 'banner' | 'faq' | 'company' | 'umrah_fare' | 'umrah_package' | 'holiday_package' | 'medical_tourism' | 'card_offer' | 'airline_offer' | 'explore' | 'app';
export type ContentStatus = 'draft' | 'published' | 'archived';
export type ContentItem = { id: string; type: ContentType; slug: string; title: string; subtitle?: string; description?: string; imageUrl?: string; mediaId?: string; metadata: Record<string, unknown>; status: ContentStatus; sortOrder: number; createdBy?: string; createdAt: string; updatedAt: string };
export type ContentFilters = { type?: ContentType | 'all'; status?: ContentStatus | 'all'; q?: string; includeArchived?: boolean };

export type AdminStats = { bookings: { total: number; new: number; reviewing: number; accepted: number; processing: number; pending: number; confirmed: number; completed: number; rejected: number; cancelled: number; failed: number }; verticalCounts: Record<Booking['vertical'], number>; revenueBdt: number; revenueTrend: Array<{ month: string; revenueBdt: number; payments: number }>; customers: number; tours: { total: number; published: number; draft: number; archived: number }; supportTickets: { total: number; open: number; pending: number; inProgress: number; waitingCustomer: number; resolved: number; closed: number }; statusDistribution: Array<{ status: BookingStatus; count: number }> };
