export type AdminCustomerDetail = AdminCustomer & { bookings: Booking[]; payments: Payment[]; notifications: Notification[]; supportTickets: SupportTicket[]; notes: CustomerNote[] };
export type CustomerNote = { id: string; userId: string; authorId?: string; note: string; createdAt: string };
export type AdminNotification = Notification & { recipient?: User; createdByUser?: User };
export type AdminAuditLog = { id: number; action: string; userId?: string; admin?: User; ip?: string; metadata: unknown; createdAt: string };

type CreateUser = { identity: string; channel: Channel; fullName?: string; role?: User['role'] };
type CreateOtp = Omit<OtpChallenge, 'createdAt'>;
type CreateSession = Omit<Session, 'createdAt'>;
type CreateBooking = { userId: string; vertical: Booking['vertical']; request: unknown; status?: BookingStatus };
type CreatePayment = { bookingId: string; userId: string; provider: string; amount: number; currency: string; status?: Payment['status'] };
type CreateTicket = Omit<SupportTicket, 'id' | 'createdAt' | 'updatedAt' | 'status' | 'priority' | 'assignedTo'> & { status?: SupportTicket['status']; priority?: SupportPriority; assignedTo?: string };
