/** Mongoose models: each persistent domain has its own collection and schema. */
const { Schema, model, models } = mongoose;
type DocModel = mongoose.Model<any>;
const mixed = Schema.Types.Mixed;
const makeModel = (name: string, collection: string, fields: Record<string, any>, indexes: Array<[Record<string, 1 | -1>, Record<string, any>?]> = []): DocModel => {
  if (models[name]) return models[name] as DocModel;
  const schema = new Schema({ id: { type: String, required: true, unique: true, index: true }, ...fields }, { versionKey: false, strict: true, collection });
  indexes.forEach(([keys, options]) => schema.index(keys, options));
  return model(name, schema, collection);
};
